; DOS L preset: Laura Bow 2 (The Dagger of Amon-Ra), Korean EUC-KR fan patch
; (2014, SIERRA/LB2CD/message.map + resource.msg + SIERRA/COMMON/korean.fnt
; in the original patch bundle - only message.map/resource.msg are used
; here; see KOREAN.TXT). Modelled on LB1KOL.MAP (same legacy EUC-KR path).
; KO2350.SVF (16 px, 1 bpp) beside this file; characters it lacks draw U+25A1.
;
; Canonical location (common2350-brief, 2026-09-29): moved here from
; harness/dos/release/lb2/ - the harness's LB2 build script now reads it
; from dists instead. The coverage gate (proper SCI1.1 message-resource
; parse of RESOURCE.MSG, not a raw byte scan) found LB2's translation needs
; 7 code points outside the 2350 (KS X 1001 extension Hangul syllables, e.g.
; U+AC37/U+D59D): folded into KO2350.SVF's own bake (bake-dos-fonts.sh,
; EXTRA_REQUIRE) rather than left to draw U+25A1.
[hires]
scale=2
alpha=false
face=ko
missing=u+25a1

[fonts]
ko=KO2350.SVF

[latin]
mode=proportional
metrics=font
